def lca_bst(nodes: list, n1: int, n2: int) -> int:
    idx = 0
    while idx < len(nodes) and nodes[idx] is not None:
        curr = nodes[idx]
        if n1 < curr and n2 < curr:
            idx = 2 * idx + 1
        elif n1 > curr and n2 > curr:
            idx = 2 * idx + 2
        else:
            return curr
    return -1
